export interface ProductionPortalRequirement {
  id: string;
  title?: string;
  brief: string;
  acceptance: string;
  source?: string;
  background?: string;
  difficulty?: string;
  kind?: string;
}
export interface ProductionPortalInput {
  packageManifest: Record<string, unknown>;
  report: unknown;
  requirements: readonly ProductionPortalRequirement[];
  runs: readonly ProductionRun[];
  jevBenchmarks: readonly JevBenchmarkRun[];
  mixedRuns: readonly ProductionRun[];
  cameraRuns?: readonly ProductionRun[];
  recordedBuildInfo?: { deploymentCommit?: string; generatedAt?: string; videoDurationSeconds?: number; videoSourceCommit?: string; historicalIframeRecording?: boolean };
  submissionBase?: string;
  previewBase?: string;
  virtualSocietyHref?: string;
  sourceHref?: string;
  snapshotHref?: string;
  /** Builder must verify each registered fixture's exact source bytes/hash first. */
  trustedFixtureIds?: readonly string[];
  /** Only the pinned archive/actual-Oracle-verified publication projection. */
  verifierStudy?: VerifierStudyMaterialSummary | null;
}

const escapeHtml = (value: unknown): string => String(value ?? '').replace(/[&<>"']/g, character => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[character]!));
function safeLink(value: string): string {
  if (/[\u0000-\u0020\\]/.test(value) || value.startsWith('//')) throw new Error('Portal URL contains unsafe characters.');
  if (/^[a-z][a-z\d+.-]*:/i.test(value)) {
    const url = new URL(value); if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password) throw new Error('Portal links must be credential-free HTTP(S).');
  }
  return escapeHtml(value);
}
function basePath(value: string): string {
  if (!/^\.?\/?[a-zA-Z\d/_-]+\/$/.test(value) || value.includes('..') || value.startsWith('//')) throw new Error('Portal asset base must be a local directory.');
  return value;
}
function caseId(value: string): string {
  if (!/^[a-zA-Z\d_-]{1,80}$/.test(value)) throw new Error('Portal requirement ID is not safe for a relative asset path.');
  return value;
}
const number = (value: number | null | undefined, digits = 0) => value == null || !Number.isFinite(value) ? 'unknown' : new Intl.NumberFormat('zh-CN', { maximumFractionDigits: digits, minimumFractionDigits: digits }).format(value);
const duration = (value: number | null | undefined) => value == null ? 'unknown' : `${number(value / 1000, 2)} 秒`;
const statusLabels: Record<string, string> = { completed: '已结束', failed: '失败', cancelled: '取消', interrupted: '中断', queued: '排队', running: '运行中', accepted: '接受候选', uncertain: '不确定 / 弃权', rejected: '拒绝候选', error: '协议 / 请求错误' };
const roleNames: Record<string, string> = { product: '产品经理', 'project-manager': '项目经理', researcher: '研究员', developer: '研发', tester: '测试', verifier: 'Verifier' };
const roles = [
  ['产品经理', '把一句话扩展为目标、范围与验收'], ['研究员', '检查约束、已知条件与未知项'], ['项目经理', '拆解任务，检查进展与有限返修'],
  ['研发', '按冻结契约生成受限 HTML / 场景数据'], ['测试', '生成验收契约并分析行为结果'], ['Verifier', '验证全部候选，可拒绝或弃权'],
] as const;

interface DecisionRecord { id: string; title: string; source: string; policyVersion: string; phase: string; evaluation: JevEvaluation | null; href: string; }
function unobservedJevRequest(evaluation: JevEvaluation): boolean {
  return !evaluation.usage.complete && evaluation.providerRequests === 0 && evaluation.durationMs === 0 && evaluation.requestSnapshot == null && evaluation.rawResponse == null && evaluation.modelIdReturned == null && evaluation.httpStatus == null && !evaluation.error;
}
function decisionRecords(input: ProductionPortalInput, submission: string): DecisionRecord[] {
  const productionRuns = uniqueRuns([...input.mixedRuns, ...(input.cameraRuns ?? [])]);
  return [
    ...input.jevBenchmarks.filter(batch => batch.evidenceSource === 'live-jev-evaluation').flatMap(batch => batch.cases.flatMap(item => item.evaluation || item.evaluationInvoked ? [{ id: `${batch.id}-${item.id}`, title: item.title, source: '固定合成候选池', phase: item.id, policyVersion: batch.policyVersion, evaluation: item.evaluation ?? null, href: `${submission}jev-benchmarks.json` }] : [])),
    ...productionRuns.filter(run => ['fixture-with-real-jev', 'real-model'].includes(run.evidenceKind)).flatMap(run => (run.jevCalls ?? []).map(call => ({ id: call.id, title: run.input.requirement.id, source: run.evidenceKind === 'fixture-with-real-jev' ? '固定研发夹具 + 真实 Jev' : '真实生产候选评审（不等于交付通过）', phase: call.phase, policyVersion: call.evaluation.policyVersion, evaluation: call.evaluation, href: `${submission}${input.cameraRuns?.some(camera => camera.id === run.id) ? 'real-camera-runs.json' : 'mixed-and-live-runs.json'}` }))),
  ];
}
function uniqueRuns(runs: readonly ProductionRun[]): ProductionRun[] {
  return [...new Map(runs.map(run => [run.id, run])).values()];
}
function hasPackageFile(input: ProductionPortalInput, name: string): boolean {
  return Array.isArray(input.packageManifest.files) && input.packageManifest.files.some(file => !!file && typeof file === 'object' && (file as { path?: unknown }).path === name);
}
